_E2 = 0.00669438   # WGS-84 eccentricity squared (geodetic to geocentric latitude)


def _cell(lat: float, lon: float):
    phi = math.degrees(math.atan((1.0 - _E2) * math.tan(math.radians(max(-89.9, min(89.9, lat))))))
    a = abs(phi)
    if a < LATS[0]:
        return None
    y = min(len(LATS) - 1.0, (a - LATS[0]) / 2.5)
    j0 = min(len(LATS) - 2, int(y))
    fy = y - j0
    x = (lon % 360.0) / LON_STEP
    i0 = int(x) % 36
    fx = x - int(x)
    return phi >= 0, i0, (i0 + 1) % 36, fx, j0, fy


def lat(lat_deg: float, lon_deg: float) -> float | None:
    """Signed CGM latitude in degrees (bilinear in the table), or None within 30 degrees of the equator."""
    c = _cell(lat_deg, lon_deg)
    if c is None:
        return None
    north, i0, i1, fx, j0, fy = c
    t = NORTH if north else SOUTH
    a = t[i0][j0] + (t[i1][j0] - t[i0][j0]) * fx
    b = t[i0][j0 + 1] + (t[i1][j0 + 1] - t[i0][j0 + 1]) * fx
    v = a + (b - a) * fy
    return v if north else -v


def midnight_ut(lat_deg: float, lon_deg: float) -> float | None:
    """UT hour (0 to 24) at which the point is at magnetic midnight (interpolated on the clock circle)."""
    c = _cell(lat_deg, lon_deg)
    if c is None:
        return None
    north, i0, i1, fx, j0, fy = c
    t = NORTH_MIDNIGHT if north else SOUTH_MIDNIGHT
    sx = sy = 0.0
    for i, wi in ((i0, 1.0 - fx), (i1, fx)):
        for j, wj in ((j0, 1.0 - fy), (j0 + 1, fy)):
            ang = t[i][j] / 1440.0 * 2.0 * math.pi
            sx += wi * wj * math.cos(ang)
            sy += wi * wj * math.sin(ang)
    return (math.atan2(sy, sx) / (2.0 * math.pi) * 24.0) % 24.0
